import torch.nn.functional as F
def lh_tf_loss(model, x, prefix=16, k=4):
    cond, tgt = x[:, :prefix], x[:, prefix:prefix + k]
    logits = model(cond)  # 用长前缀预测后续帧
    return F.cross_entropy(logits.reshape(-1, logits.size(-1)),
                           tgt.reshape(-1))

def dmd_loss(student_score, real_score, x_t, t):
    diff = student_score(x_t, t) - real_score(x_t, t)
    return (diff ** 2).mean()  # 近似的分布匹配损失

import torch
def pick_unique_route(route_logits):
    # route_logits[st] 为该通信对候选无环路由的打分
    # 每次只选一条 => 天生满足 sum_r y_r == 1
    return [int(torch.multinomial(l.softmax(-1), 1))
            for l in route_logits]

import numpy as np
def wer(ref, hyp):
    r, h = ref.split(), hyp.split()
    d = np.zeros((len(r)+1, len(h)+1), dtype=int)
    d[:, 0] = range(len(r)+1); d[0, :] = range(len(h)+1)
    for i in range(1, len(r)+1):
        for j in range(1, len(h)+1):
            d[i, j] = min(d[i-1, j]+1, d[i, j-1]+1,
                          d[i-1, j-1] + (r[i-1] != h[j-1]))
    return d[-1, -1] / max(len(r), 1)
